function makeDirectory(entries) {
  if (!Array.isArray(entries)) {
    throw new TypeError('entries must be an array');
  }

  const seen = new Set();
  const records = entries.map((entry) => {
    if (
      entry === null ||
      typeof entry !== 'object' ||
      typeof entry.code !== 'string' ||
      entry.code.length === 0 ||
      typeof entry.title !== 'string' ||
      entry.title.length === 0
    ) {
      throw new TypeError('each entry must have a non-empty code and title');
    }
    if (seen.has(entry.code)) {
      throw new TypeError('entry codes must be unique');
    }
    seen.add(entry.code);
    return { code: entry.code, title: entry.title };
  });

  return {
    get(code) {
      if (typeof code !== 'string') {
        throw new TypeError('code must be a string');
      }
      const record = records.find((item) => item.code === code);
      return record ? { ...record } : null;
    },

    search(term, limit = records.length) {
      if (typeof term !== 'string') {
        throw new TypeError('term must be a string');
      }
      if (!Number.isInteger(limit) || limit < 0) {
        throw new TypeError('limit must be a non-negative integer');
      }
      const needle = term;
      return records
        .filter((item) => item.title.toLowerCase().includes(needle))
        .slice(0, limit)
        .map((item) => ({ ...item }));
    }
  };
}

module.exports = { makeDirectory };

