'use strict';
const assert = require('node:assert');
const api = require('./solution');
assert.deepStrictEqual(Object.keys(api).sort(), ['makeDirectory']);
const { makeDirectory } = api;

for (const bad of [null, undefined, {}, 'x', 1, true]) {
  assert.throws(() => makeDirectory(bad), TypeError);
}
for (const bad of [
  [null], [[]], [{}],
  [{ code: '', title: 'Title' }],
  [{ code: 'A', title: '' }],
  [{ code: 1, title: 'Title' }],
  [{ code: 'A', title: 1 }],
  [{ code: 'A', title: 'One' }, { code: 'A', title: 'Two' }]
]) {
  assert.throws(() => makeDirectory(bad), TypeError);
}

const empty = makeDirectory([]);
assert.strictEqual(empty.get('missing'), null);
assert.deepStrictEqual(empty.search(''), []);
assert.throws(() => empty.search(1), TypeError);
assert.throws(() => empty.search('', -1), TypeError);
assert.throws(() => empty.search('', 1.5), TypeError);

const input = [
  { code: 'a1', title: 'Alpha Project' },
  { code: 'b2', title: 'beta ALPHA' },
  { code: 'c3', title: 'Gamma' }
];
const directory = makeDirectory(input);
input[0].title = 'changed';
input.push({ code: 'd4', title: 'Alpha later' });
assert.deepStrictEqual(directory.get('a1'), { code: 'a1', title: 'Alpha Project' });
assert.strictEqual(directory.get('nope'), null);
assert.deepStrictEqual(directory.search('ALpHa'), [
  { code: 'a1', title: 'Alpha Project' },
  { code: 'b2', title: 'beta ALPHA' }
]);
assert.deepStrictEqual(directory.search('', 2), [
  { code: 'a1', title: 'Alpha Project' },
  { code: 'b2', title: 'beta ALPHA' }
]);
assert.deepStrictEqual(directory.search('a', 0), []);
assert.deepStrictEqual(directory.search('not present'), []);
assert.throws(() => directory.search(null), TypeError);
for (const badLimit of [-1, 1.2, NaN, Infinity, '2', null]) {
  assert.throws(() => directory.search('', badLimit), TypeError);
}
const firstGet = directory.get('a1');
firstGet.title = 'mutated result';
assert.strictEqual(directory.get('a1').title, 'Alpha Project');
const firstSearch = directory.search('alpha');
firstSearch[0].title = 'mutated search';
firstSearch.pop();
assert.deepStrictEqual(directory.search('alpha'), [
  { code: 'a1', title: 'Alpha Project' },
  { code: 'b2', title: 'beta ALPHA' }
]);
assert.notStrictEqual(directory.get('a1'), directory.get('a1'));

